"""PyTorch dataset for AISSLab Axial detection manifests."""
from __future__ import annotations

import csv
import json
from pathlib import Path

import torch
from PIL import Image
from torch.utils.data import Dataset

from .transforms import DetectionToTensor


class AxialDetectionDataset(Dataset):
    """Load annotated images from a manifest generated by audit_dataset.py.

    Unannotated images are excluded by default because missing XML is not a
    verified negative label. `include_empty_xml=True` includes valid empty XML
    samples only when the annotation policy confirms they are true negatives.
    """

    def __init__(
        self,
        csv_path,
        root=".",
        class_map_path="DATA/metadata/detection_class_map.json",
        transform=None,
        include_empty_xml=False,
    ):
        self.root = Path(root)
        self.transform = transform or DetectionToTensor()
        with open(csv_path, newline="", encoding="utf-8-sig") as f:
            all_rows = list(csv.DictReader(f))

        allowed = {"annotated"}
        if include_empty_xml:
            allowed.add("empty_xml")
        self.rows = [
            row for row in all_rows
            if row.get("annotation_status") in allowed and row.get("image_path")
        ]
        if not self.rows:
            raise ValueError(
                f"No trainable annotated samples in {csv_path}. "
                "Run audit_dataset.py and inspect annotation_status first."
            )

        with open(class_map_path, encoding="utf-8") as f:
            self.class_map = json.load(f)

    def __len__(self):
        return len(self.rows)

    def __getitem__(self, index):
        row = self.rows[index]
        image_path = self.root / row["image_path"]
        image = Image.open(image_path).convert("L")
        objects = json.loads(row["objects_json"] or "[]")

        boxes = [obj["bbox"] for obj in objects]
        labels = [self.class_map[obj["name"]] for obj in objects]
        target = {
            "boxes": torch.tensor(boxes, dtype=torch.float32).reshape(-1, 4),
            "labels": torch.tensor(labels, dtype=torch.int64),
            "image_id": torch.tensor([index], dtype=torch.int64),
            "area": torch.tensor(
                [(b[2] - b[0]) * (b[3] - b[1]) for b in boxes],
                dtype=torch.float32,
            ),
            "iscrowd": torch.zeros((len(boxes),), dtype=torch.int64),
            "patient_id": row["patient_id"],
            "image_path": row["image_path"],
        }

        image, target = self.transform(image, target)
        return image, target